       "body": "• <b>OJT (직장 내 교육)</b>: 직속상사가 실무 작업표준으로 개별 지도. 즉각적 개선 가능<br>\n• <b>Off JT (직장 외 교육)</b>: 다수 근로자 집합 교육, 체계적 지식 전달 및 외부 전문가 초빙<br>\n• <b>TWI (감독자 훈련) 4대 과정</b>:<br>\n  - <b>JIT</b>: 작업지도훈련 (Job Instruction)<br>\n  - <b>JMT</b>: 작업방법훈련 (Job Method)<br>\n  - <b>JRT</b>: 인간관계훈련 (Job Relation)<br>\n  - <b>JST</b>: 작업안전훈련 (Job Safety)",
