       "body": "• <b>패널디스커션</b>: 전문가 4~5명이 청중 앞에서 토의 후 청중 전원 참가 질의토의<br>\n• <b>심포지엄</b>: 몇몇 전문가가 각자의 견해를 발표한 후 참가자와 질의응답<br>\n• <b>포럼</b>: 새로운 자료 제시 후 참가자 스스로 문제 제기하여 심층 토의<br>\n• <b>버즈세션 (6-6 회의)</b>: 6명씩 소집단을 구성해 6분간 자유토론 후 전체 종합<br>\n• <b>사례연구법</b>: 실제 사례를 제시하고 문제점 분석 및 대책 토의",
