       "body": "**산업안전보건법**: **175개 조문**과 부칙. **1개 법률 + 1개 시행령 + 3개 시행규칙**(시행규칙, 산업안전보건기준에 관한 규칙, 유해·위험작업의 취업 제한에 관한 규칙)\n**하위**: 고시(약 **80여개**), 예규, 훈령 → 기술상의 지침, 작업환경표준(**강제력 없음**, 지도·권고적 성격)\n**KOSHA GUIDE**: 자율적 안전보건가이드, **법적 구속력 없음**. 번호부여 = KOSHA GUIDE + 분야기호 + 세부분야기호 + 일련번호 + 발행연도 (예: **A-G-1-2024**)\n**분야기호**: 산업안전일반 **A**, 기계·전기안전 **M**, 화학안전 **C**, 건설안전 **D**, 보건·위생 **E**",
