       "body": "**PHA**: 구상단계의 최초 정성적 분석. 위험등급 Class 1 파국 / 2 중대(위기) / 3 한계적 / 4 무시가능\n**FHA**: 분업 설계된 서브시스템 간 인터페이스 조정, 정의·개발단계 적용\n**FMEA**: 귀납적·정성적. 고장형태별 영향 분석. 2개 이상 동시 고장·인적 원인 분석 곤란\n**CA**: 고장을 정량적·귀납적으로 위험도 평가(항공기)\n**THERP**: HEP 정량 예측(100만 운전시간당)\n**MORT**: 원자력 등 고도 안전성 확보(Johnson)\n**FTA**: 연역적·정량적, Top down (1962 벨연구소 Watson)\n**ETA/DT**: 귀납적·정량적, 확률합 1.0\n**FAFR**: 10⁸시간당 사망자수(Kletz)\n**HAZOP**: 공정·설계도의 체계적·비판적 검토",
