       "body": "**예방보전(Preventive Maintenance)**: 설비를 항상 정상·양호한 상태로 유지하기 위한 정기적 검사와 초기 단계에서 성능 저하·고장을 제거·조정·수복하는 보수 활동\n· 시간계획보전(예정된 시간계획) / 상태감시보전(이상상태를 미리 검출) / 수명보전(예정된 동작시간 도달 시)\n**일상보전(Routine Maintenance)**: 열화를 방지하고 진행을 지연시켜 수명을 연장 — 점검, 청소, 주유, 교체\n**사후보전(Breakdown Maintenance)**: 고장 발생 이후 원래 상태로 되돌리는 것\n**교체주기**: 수명교체(고장 시 즉시 + 교체주기 도달 시) / 일괄교체(고장 없어도 관련부품 일괄 — 교체비용 절감)\n※ 마모고장기(IFR)의 예방대책이 바로 **예방보전(PM)**",
