       "body": "**1. 법령 규정 사항 확인**: 「산업안전보건법령」 등에 규정된 사항이 있는지 검토하여 법령에 규정된 방법으로 조치\n**2. 본질적(근원적) 대책**: 위험한 작업을 **폐지**하거나 기계·기구·물질의 **변경 또는 대체**로 위험을 근원적으로 제거 — **최우선 고려**\n**3. 공학적 대책**: **인터록, 안전장치, 방호문, 국소배기장치** 설치 등으로 유해성이나 접근 가능성을 줄임\n**4. 관리적 대책**: 작업 매뉴얼 정비, **출입금지·작업허가 제도**, 주의사항 교육\n**5. 개인보호구 사용**: 위 조치들로도 줄이기 어려운 위험에 대한 **최후의 방법**\n**빈도·강도법**: 위험성의 **빈도(가능성) × 강도(중대성)**로 크기를 산출하고 사전에 정한 **허용 가능한 위험성의 크기**와 비교하여 허용 가능/불가능을 판단",
