       "body": "**보전**: 설비·제품의 고장이나 결함을 회복시키기 위한 수리·교체 등을 통해 시스템을 사용가능한 상태로 유지시키는 것\n**예방보전(PM)**: 정기적인 검사와 초기 단계의 성능저하·고장 제거·조정·수복 — **시간계획보전**(예정된 시간계획)과 **상태감시보전**(이상상태를 미리 검출)으로 나뉨\n**사후보전(BM)**: 고장이 발생한 후 수리\n**개량보전(CM)**: 설비 자체의 체질 개선\n**보전예방(MP)**: 설계 단계에서 보전이 불필요한 설비를 지향\n**신뢰성 지표**\n**MTBF**(평균고장간격) = MTTF + MTTR, **MTTF**(평균동작시간), **MTTR**(평균수리시간)\n**가용도 A = MTTF/(MTTF+MTTR) = MTTF/MTBF**\n**가용도 A = μ/(λ+μ)** (λ: 평균고장률, μ: 평균수리율)\n**휴먼에러 대책 3종**: **배타설계**(근원적 제거) → **보호설계(풀프루프)**(에러 확률 최소화) → **이중안전설계(페일세이프)**(안전장치 부착, 병렬·대기 중복설계)\n**병렬체계 특성**: 어느 하나라도 정상이면 시스템 정상 / 중복도가 늘수록 수명 증가 / **시스템 수명은 요소 중 수명이 가장 긴 것**으로 결정",
