       "body": "**SPL[dB] = 20log(P/P₀)**, P₀=20μN/m²\n거리 변화: **dB₂ = dB₁ - 20log(d₂/d₁)**\n소음 합성: **SPL = 10log(10^(A₁/10)+10^(A₂/10)+…)**\n**Phon**: 1,000Hz 순음의 음압수준[dB]과 같은 크기\n**Sone**: 40dB 1,000Hz(=40phon)를 1sone. **sone = 2^((phon-40)/10)**\n**은폐(Masking)**: 다른 음 때문에 가청 역치가 높아지는 현상\n등감곡선: 20~20,000Hz / 0~130dB, **4,000Hz에서 가장 예민**, 100Hz 이하 둔감\n청력손실은 **4,000Hz(C5-dip)**에서 최대",
