       "body": "**풀프루프(Fool Proof)**: 작업자가 **실수를 하더라도** 기계가 사고로 이어지지 않는 구조 — 대표 사례가 **인터록(Interlock)**\n**페일세이프(Fail Safe)**: 기계·부품이 **고장나더라도** 안전한 쪽으로 작동하는 구조\n**페일세이프 3단계** ★★★\n**Fail Passive**: 고장 시 **기계가 정지** — 일반적인 기계 방식\n**Fail Active**: 고장 시 **경보를 울리며 단시간 운전** 가능\n**Fail Operational**: 고장이 있어도 **다음 점검·보수 때까지 운전 가능** — **가장 이상적**\n**페일세이프의 기능적 분류**: **다경로 하중구조**, **하중경감구조**, **교대구조**, **중복구조**\n**방호장치의 분류** ★★★\n**격리형**: 완전차단형·덮개형·안전방책 — 작업자와 위험점을 분리\n**위치제한형**: **양수조작식** — 신체를 위험한계 밖에 두게 함\n**접근거부형**: **수인식·손쳐내기식** — 접근하는 신체를 밀어냄\n**접근반응형**: **광전자식(감응형)** — 접근을 감지해 기계를 정지\n**포집형**: 연삭숫돌 덮개 — 위험원이 비산하지 않도록 포집",
       "id": "S3-CH1-n5"
