       "body": "**가드 개구부의 간격(KOSHA M-135)** ★★★\n일반적인 개구부: **Y = 6 + 0.15X** (X < 160mm), 단 **X ≥ 160mm이면 Y = 30mm**\n위험점이 **전동체**인 경우: **Y = 6 + 0.1X** (X < 760mm에서 유효)\nY: 개구부의 간격[mm], X: 개구부에서 위험점까지의 최단거리[mm]\n공간함정(Trap)을 막기 위한 가드와 손가락의 **최소 틈새는 25mm**\n**급정지거리** ★★★\n앞면 롤러의 표면속도 **30m/min 미만** → 앞면 롤러 **원주의 1/3 이내**\n앞면 롤러의 표면속도 **30m/min 이상** → 앞면 롤러 **원주의 1/2.5 이내**\n**표면속도 V = πDN/1,000 [m/min]** (D: 롤러 지름[mm], N: 분당회전수[rpm])\n**급정지장치 조작부 위치**(중심점 기준) ★★★\n**손조작식: 밑면에서 1.8m 이내**\n**복부조작식: 밑면에서 0.8m 이상 1.1m 이내**\n**무릎조작식: 밑면에서 0.6m 이내**\n조작부는 롤러기 **전면 및 후면에 각각 1개씩 수평**으로 설치하고 길이는 **롤러의 길이 이상**",
