       "body": "**하역작업 시 전후: 4% 이내** (5톤 이상 **3.5% 이내**)\n**주행 시 전후: 18% 이내**\n**하역작업 시 좌우: 6% 이내**\n**주행 시 좌우: (15 + 1.1V)% 이내** (V = 구내 최고속도 km/h)\n안정도 = h/l × 100[%]\n안정 조건: M₁ ≤ M₂ → **W × L₁ ≤ G × L₂**\n**헤드가드**: 최대하중 **2배**(4톤 초과 시 4톤) 등분포정하중, 개구 폭·길이 **16cm 미만**, 높이 입승식 1.88m·좌승식 0.903m 이상",
