       "body": "**양중기 5종**: 크레인, 이동식 크레인, 리프트, 곤돌라, 승강기\n방호장치: 과부하방지장치, 권과방지장치, 비상정지장치 및 제동장치 (+승강기 파이널 리미트 스위치, 속도조절기, 출입문 인터록)\n**권과방지장치 간격: 0.25m 이상(직동식 0.05m 이상)**\n**풍속**: 주행 크레인 이탈방지 **30m/s 초과** / 건설용 리프트 붕괴방지 **35m/s 초과**\n**안전계수**: 근로자 탑승 운반구 **10 이상** / 화물 하중 직접 지지 **5 이상** / 훅·샤클·클램프·리프팅 빔 **3 이상** / 그 밖 **4 이상**\n**와이어로프 사용금지**: 이음매 있는 것 / 한 꼬임 소선 **10% 이상** 절단 / 지름 감소 공칭지름 **7% 초과** / 꼬인 것 / 심한 변형·부식 / 열·전기충격 손상\n**체인 사용금지**: 길이 **5% 초과** 늘어남 / 링 단면지름 **10% 초과** 감소 / 균열·심한 변형",
