       "body": "**양중기 5종**: **크레인**(호이스트 포함) / **이동식 크레인** / **리프트**(이삿짐운반용은 적재하중 **0.1톤 이상**) / **곤돌라** / **승강기**\n**승강기의 종류**: 승객용 / 승객화물용 / **화물용**(적재용량 **300kg 미만**은 제외) / **소형화물용**(사람 탑승 금지) / 에스컬레이터\n**공통 방호장치 4종**: **과부하방지장치 · 권과방지장치 · 비상정지장치 · 제동장치**\n**그 밖의 방호장치**(승강기): **파이널 리미트 스위치, 속도조절기, 출입문 인터 록**\n**권과방지장치 조정** ★★★: 훅·버킷 등 달기구의 윗면이 드럼·상부 도르래·트롤리프레임 등 권상장치의 아랫면과 접촉할 우려가 있는 경우 그 **간격이 0.25m 이상**(**직동식은 0.05m 이상**)이 되도록 조정\n권과방지장치를 설치하지 않은 크레인은 **권상용 와이어로프에 위험표시**를 하고 **경보장치**를 설치\n**과부하의 제한**: 양중기에 **적재하중을 초과하는 하중**을 걸어서 사용 금지\n**건설용 리프트 붕괴 방지**: 순간풍속이 **35m/s를 초과**할 우려가 있으면 받침의 수를 증가시키는 등 조치",
