       "body": "**표면결함 검출**: 육안검사 VT / 침투탐상 PT / 자분탐상 MT(강자성체, 누설자속) / 와류탐상 ECT(교류 코일, 전압·전류 변화)\n**내부결함 검출**: 방사선투과 RT / 초음파탐상 UT(**균열 등 면상결함 검출능력이 RT보다 우수**, 투과법·펄스반사법·공진법)\n**기타**: 누설검사 LT / 음향탐상 AET(응력파 분석) / 중성자선투과 NRT / 스트레인측정 SM / 경도검사 HT / 재료확인시험 PMI\n**고속회전체**: 원주속도 **25m/s 초과** → 격리 장소에서 회전시험 / 회전축 중량 **1톤 초과 + 원주속도 120m/s 이상** → 비파괴검사",
