       "body": "**설비진단 3단계**: **간이진단**(이상 유무 판정) → **정밀진단**(원인·부위 규명) → **경향관리**(추이 감시로 수명 예측)\n**진동 측정량의 적용**: 저주파 → **변위**, 중간 → **속도**, 고주파 → **가속도**\n**예지보전(CBM)**: 상태감시로 고장 징후를 미리 파악하여 필요한 시점에만 보전\n**안전검사 주기(산업안전보건법 시행규칙 제126조)** ★★★\n**크레인(이동식 제외)·리프트(이삿짐운반용 제외)·곤돌라**: 설치가 끝난 날부터 **3년 이내** 최초 검사, 이후 **2년마다**(**건설현장은 최초 설치한 날부터 6개월마다**)\n**이동식 크레인·이삿짐운반용 리프트·고소작업대**: **신규등록 이후 3년 이내** 최초 검사, 이후 **2년마다**\n**프레스·전단기·압력용기·국소배기장치·원심기·롤러기·사출성형기·컨베이어·산업용 로봇**: 설치가 끝난 날부터 **3년 이내** 최초 검사, 이후 **2년마다**(공정안전보고서 이행 사업장의 압력용기는 **4년마다**)\n**자율검사프로그램**: 안전검사 주기의 **1/2에 해당하는 주기마다** 검사하고, 검사원을 두거나 검사기관에 위탁",
