       "body": "**수전반**: 한국전력으로부터 **전기를 인수받는 곳**. 계기용변성기(MOF), 피뢰기(LA), 차단기 등\n**배전반**: 수전한 전기를 **각 계통으로 나누어 보내는** 설비. 주차단기와 분기차단기로 구성\n**분전반**: 배전반에서 받은 전기를 **최종 부하로 분기**하는 설비\n**분전반 설치기준**\n분기회로에는 **감전보호용 지락과 과부하 겸용의 누전차단기**를 설치\n철제 분전함의 **외함은 반드시 접지**를 실시\n문에 **시건장치**를 하고 **\"취급자 외 조작금지\"** 표지를 부착\n**전기설비 안전관리 기본**\n**2021년부터 한국전기설비규정(KEC)** 적용 — 접지·전압 구분 등 개정 사항이 많다\n**전압 구분(KEC 111.1)**: 저압 교류 **1kV**·직류 **1.5kV** 이하 / 고압 그 초과~**7kV** 이하 / **특고압 7kV 초과**",
