       "body": "**유입차단기(OCB)**: **절연유**를 소호매질로 사용. 고압·특고압용\n**진공차단기(VCB)**: **고진공** 중의 전자 확산을 이용. 소형·경량, 보수 용이\n**가스차단기(GCB)**: **SF₆(육불화황) 가스** 사용. 대전류 차단 성능 우수, 초고압용\n**공기차단기(ABB)**: **압축공기**로 아크를 불어 끔. 대전류용\n**자기차단기(MBB)**: **전자력**으로 아크를 소호실로 유도\n**기중차단기(ACB)**: **대기 중**에서 아크를 소호. 저압용\n**배선용 차단기(MCCB)**: 저압 옥내선로 보호용\n**개폐기와 차단기의 차이** ★★\n**개폐기**: 전로의 **개폐에만** 사용, **통전상태에서 차단능력 없음**\n**단로기(DS)**: **무부하 상태**의 전로 개폐, **전압 개폐 기능만**\n**조작순서**: 투입 시 **단로기 → 차단기**, 개방 시 **차단기 → 단로기**\n**부하개폐기(LBS)**: 부하전류는 개폐 가능, **고장전류 차단 불가** → **전력퓨즈 병용**\n**정격차단용량**: 3상 = **√3 × 정격차단전압 × 정격차단전류**, 단상 = 정격차단전압 × 정격차단전류",
