       "body": "**기체**: 확산연소(기체의 일반적 형태) / 예혼합연소\n**액체**: **증발연소(액체의 가장 일반적 형태)** / 분무연소\n**고체**\n· **표면연소**: 불꽃 없음 — 코크스, 목탄, 금속분\n· **분해연소**: 목재, 종이, 석탄, 플라스틱\n· **증발연소**: 황, 나프탈렌, 파라핀\n· **자기연소**: 외부 산소 불필요 — 질산에스테르류, 셀룰로이드류, 니트로화합물\n**백드래프트**: 폐쇄공간 화재에서 문을 열어 산소 공급 → 연소가스 순간 발화",
       "id": "S5-CH1-n2"
