       "body": "**기상폭발**: 혼합가스폭발 / 가스 분해폭발 / **분진(분무)폭발**\n**응상폭발**: 수증기폭발 / 증기폭발 / 전선폭발 / 고상 간 전이에 의한 폭발\n**분진폭발**\n· 입자 크기 **75μm 이하**\n· 순서: **퇴적분진 → 비산 → 분산 → 발화원 → 전면폭발 → 2차 폭발**\n· 특징: **가스폭발보다 발생에너지 大, 폭발압력·연소속도는 小**, 불완전 연소로 가스중독 위험 大, 2·3차 폭발 파급\n· 영향인자: 입경 작을수록·표면적 클수록·수분 작을수록 위험, **부유분진이 퇴적분진보다 발화온도 높음**\n· 시험장치: **하트만(Hartmann)식**, 불활성 첨가물: 탄산칼슘·모래·석분·질석가루",
       "id": "S5-CH1-n3"
