       "body": "**A급 일반화재 백색 / B급 유류화재 황색 / C급 전기화재 청색 / D급 금속화재 색 없음**\n**보일 오버**: 유류탱크 화재 시 열파가 저부 물에 도달 → 기름 분출\n**슬롭 오버**: 화염 표면에 물·포 방사 → 위험물과 함께 넘침\n**소화의 4종류**\n· **제거소화**: 가연물 공급 중단\n· **질식소화**: 포·분말·CO₂·할로겐·마른모래·팽창질석\n· **냉각소화**: 물, 강화액, 산·알칼리\n· **억제소화**: 할론(부촉매 작용)\n금속화재(D급)는 **물 사용 금지**, 건조사·팽창 진주암으로 질식소화",
       "id": "S5-CH1-n6"
