       "body": "**최소산소농도(MOC)**: 인화성 가스 **10%**, 가연성 분진 **8%**, 인화성 액체 증기 **12~16%**, 표면화재 5% 이하, 심부화재 2% 이하\n**불활성화(Inerting)**: 불활성 가스(질소·CO₂·수증기·연소배기가스) 주입으로 산소를 MOC 이하로 유지\n→ 관리 산소농도는 **MOC보다 4% 정도 낮게**\n**퍼지 4방법**: 진공퍼지(큰 용기 곤란, 가스 소모 적음·시간 김) / 압력퍼지 / **스위프퍼지(비관류)** / 사이폰퍼지(액체 채움)\n최대 불활성 가스값: 온도·압력 증가 시 증가",
