       "body": "**연소파 0.1~1.0m/s / 폭굉파 1,000~3,500m/s**(음속 초과 → 충격파)\n**폭발한계 > 폭굉한계**(폭굉은 폭발 후 발생)\n**폭굉 유도거리가 짧아지는 조건**: 정상 연소속도가 큰 혼합물 / 점화원 에너지 큼 / 고압 / 관 속 방해물 / **관경이 작을 때**\n**폭발위력 거리: r₂ = r₁(W₂/W₁)^(1/3)**\n**최대폭발압력 영향**: 초기온도↑→감소 / **초기압력↑→증가** / 농도↑→증가 / 발화원 강도↑→증가 / **용기 작을수록 증가**\n**최소발화에너지(MIE)**: 압력↑→감소 / 불활성 물질↑→증가 / **공기 중이 산소 중보다 높음** / **유속↑→커짐** / 양론농도보다 조금 높을 때 최소\n**E = (1/2)CV²**\n**안전간격(화염일주한계)이 작을수록 폭발 위험 大** (표준용기 8L)",
