       "body": "**LD/MLD/LD50/LD100**, **LC/MLC/LC50/LC100**\n**고독성 물질: 경구 LD50 25mg/kg 이하**\n**TWA = (C₁T₁+C₂T₂+…)/8** (1일 8시간 기준)\n**STEL: 15분**간 평균, 1회 15분 미만, **1일 4회 이하**, 간격 **60분 이상**\n**Ceiling(최고노출기준)**: 잠시라도 노출 금지\n**혼합물 위험도 R = ΣCi/Ti ≤ 1**\n**노출기준(TWA)**: 포스겐·불소·브롬 **0.1ppm** / 염소 0.5 / 황화수소 10 / 암모니아 25 / 일산화탄소 30 / 톨루엔 50ppm\n**유독물 입자 크기**: 흄·스모크 0.01~1μm / 미스트 0.1~100μm / 분진 0.01~500μm\n**유해지수 K = 농도 × 노출시간**(Hafer의 법칙)",
