       "body": "**교육훈련**: 비상조치계획에 따라 사고발생 시 신속하고 효과적으로 대응조치를 취할 수 있도록 계획에 규정된 인력들이 각자의 역할을 숙지하고 실행하는 교육훈련이 필요하다.\n\n**평가** — 비상조치계획은 **사고 발생을 가정하여 정기적으로 재검토**하고, 미비점이 발견될 시 보완한다.\n**평가 대상**\n① 비상조치계획의 **정확성, 일관성 및 완성도와 실행 가능성** 그리고 관련 문서 전반\n② 사용 **장비 및 시설의 적절성 및 사용용이성**\n③ 계획 **실행자의 수행 능력** 또는 장비·시설 사용 능력\n④ **현장 통제센터의 기능과 역할**\n⑤ **경보시스템**\n\n**교육훈련 및 평가 방법**\n① 화재훈련, 경보 테스트, 소개 및 탐색, 통신 등에 대한 **직접 점검**\n② **세미나 토의**를 통한 평가\n③ **온라인을 통한 모의 훈련**\n④ 비상조치계획의 **수정 및 보완**",
