       "body": "**중대산업사고(산업안전보건법 제44조)**: 대통령령으로 정하는 유해하거나 위험한 설비로부터의 **위험물질 누출, 화재 및 폭발** 등으로 인하여 **사업장 내의 근로자에게 즉시 피해를 주거나 사업장 인근 지역에 피해를 줄 수 있는 사고**\n**중대재해와 구분** ★★\n**중대재해**: 사망자 **1명 이상** / **3개월 이상** 요양 부상자 동시 **2명 이상** / 부상자 또는 직업성 질병자 동시 **10명 이상** — **인명 피해 기준**\n**중대산업사고**: **누출·화재·폭발**로 사업장 내외에 피해를 줄 수 있는 사고 — **사고 유형 기준**\n**공정안전 리더십(KOSHA P-19)**\n관리자들은 공정안전문화의 **비전·기댓값·역할·책임사항**을 알아야 한다\n신임 및 기존 관리자에게 공정안전문화에 대한 **공식적인 훈련 프로그램**을 제공하고 **주기적으로 개정**\n관리자는 공정안전에 대한 **가치·우선순위·관심분야**를 자발적으로 표현할 기회를 찾는다\n회사의 **모든 계층**이 공정안전 리더십에 대한 책임과 의무를 나누어야 한다",
       "id": "S5-CH3-n5"
