       "body": "**공동현상(Cavitation)**: 정압이 증기압보다 낮아 증기 발생\n· 발생조건: 흡입양정 과대 / 유량 증대 / **흡입관 저항 증대** / **관내 온도 상승**\n· 예방: **회전수 낮춤** / 흡입비 속도 작게 / Head 손실 감소 / **설치위치 낮춤**\n**수격작용**: 유속 급변으로 압력변화\n**서징**: 주기적으로 운동·양정·토출량 변동 → 풍량 감소, 배관 경사 완만, **교축밸브 가까이**, 바이패스\n**상사법칙**: **Q∝N / P∝N² (∝D²) / L∝N³**\n**왕복식 압축기 이상음**: 실린더 주변(틈새 과대·피스톤 마모·이물질) / 크랭크 주변(베어링·크로스헤드 마모)\n**가스누출감지경보기**: 가연성 **폭발하한계 25% 이하**, 독성 허용농도 이하 / 정밀도 가연성 ±25%, 독성 ±30% 이하 / 비중 무거우면 **하부**, 가벼우면 상부",
