       "body": "**안전관리조직의 기본 역할**\n시공 중인 **구축물 등 공사장 및 공사장 주변의 안전 확보**\n**안전관리계획서에 따른 안전시공 여부 확인**\n**안전교육의 실시**\n**안전사고 예방 및 긴급조치**\n**제반 위험요소의 제거**\n비상사태 시 **응급조치 및 복구**\n조직 구성 시 **구성원의 책임과 권한을 명확히** 하고 **현장 여건을 충분히 고려**해야 한다\n**안전보건관리체계** ★★\n**사업주**: 근로자를 사용하여 사업을 하는 사람\n**안전보건관리책임자**: 사업장을 **실질적으로 총괄하여 관리**하는 사람\n**안전보건총괄책임자**: 관계수급인 근로자가 도급인 사업장에서 작업하는 경우 **도급인·수급인 근로자의 산업재해 예방 업무를 총괄 관리**하도록 지정\n**관리감독자**: 생산 관련 업무와 소속 직원을 **직접 지휘·감독**하는 직위에 있는 사람\n**안전·보건관리자**: 기술적 사항에 관하여 **사업주·안전보건관리책임자를 보좌**하고 **관리감독자에게 지도·조언**",
