       "body": "**안전난간 구성**: 상부난간대 + 중간난간대 + **발끝막이판** + 난간기둥\n· 상부난간대: 바닥면 등으로부터 **90cm 이상**\n· 상부난간대 **120cm 이하** 설치 → 중간난간대는 상부난간대와 바닥면의 **중간**\n· 상부난간대 **120cm 이상** 설치 → 중간난간대 **2단 이상 균등**, 상하 간격 **60cm 이하**\n· 발끝막이판: 바닥면 등으로부터 **10cm 이상**\n· 난간대: 지름 **2.7cm 이상** 금속제 파이프\n· 하중: **100kg 이상**에 견딜 것\n· 설치위치: 작업발판 및 통로의 단부, 개구부, 터파기 사면, 흙막이 가시설 상단\n\n**작업발판(비계 높이 2m 이상)**\n· 폭 **40cm 이상**, 발판재료 간 틈 **3cm 이하**\n· 선박·보트 좁은 공간 → 폭 **30cm 이상**, 걸침비계 틈 **5cm 이하** 가능\n· 재료는 **둘 이상의 지지물**에 연결·고정\n· 최대적재하중을 정하고 초과 적재 금지",
