       "body": "**경사로** — 경사 **30° 이내**\n| 경사각 | 미끄럼막이 간격 | 경사각 | 미끄럼막이 간격 |\n|---|---|---|---|\n| 30° | **30cm** | 22° | 40cm |\n| 29° | 33cm | 19°20′ | 43cm |\n| 27° | 35cm | 17° | 45cm |\n| 24°15′ | 37cm | 14° | **47cm** |\n· 폭 **최소 90cm 이상**\n· **높이 7m 이내마다 계단참**\n· 지지기둥 **3m 이내마다**\n· 발판 폭 **40cm 이상**, 틈 **3cm 이내**\n· 추락방지용 안전난간 설치, 목재는 미송·육송 이상\n\n**가설계단** — 경사 **35°**가 적정\n| 구분 | 설치기준 |\n|---|---|\n| 강도 | **500kg/m² 이상** 하중, **안전율 4 이상** |\n| 폭 | **1m 이상**, 손잡이 외 물건 설치·적재 금지 |\n| 계단참 | 높이 **3m 초과** 시 **3m 이내마다 너비 1.2m 이상** |\n| 난간 | 높이 **1m 이상** 계단의 개방된 측면에 안전난간 |\n\n**가설발판 휨응력**: σ = ±(M/I)·y / σ_max = ±M_max/Z, **Z = bh²/6** / 등분포 **M_max = wl²/8**, 집중 **M_max = Pl/4**",
