       "body": "**구조검토 시 고려 하중 4가지**\n① **연직방향 하중**: 거푸집·지보공·콘크리트·철근·작업원·타설용 기계기구·가설설비의 중량 및 충격하중\n② **횡방향 하중**: 진동·충격·시공오차 기인 횡방향 하중, 풍압·유수압·지진\n③ **콘크리트 측압**: 굳지 않은 콘크리트의 측압\n④ **특수하중**: 콘크리트 편심하중 등\n\n**연직방향 하중 계산식**\n**W = 고정하중 + 작업하중 = γ×t + 40[kg/m²] + 250[kg/m²]**\n(γ: 철근콘크리트 단위중량, t: 슬래브 두께)\n\n· **고정하중**: 거푸집 무게 최소 **0.4kN/m²** 이상\n· **작업하중**: 타설 높이 0.5m 미만 **2.5kN/m²** / 0.5~1.0m 미만 **3.5kN/m²** / 1.0m 이상 **5.0kN/m²**\n· **합산 연직하중**: 타설 높이 무관 **5.0kN/m² 이상**\n\n**조립도**: 부재의 **재질·단면규격·설치간격 및 이음방법** 명시",
       "id": "S6-CH5-n6"
