       "body": "**공통(제332조)**\n· 받침목·깔판 사용 등 **침하 방지**\n· 상하 고정 및 **미끄러짐 방지**\n· 상부·하부 동바리가 **동일 수직선 상**에 위치\n· 개구부 상부 설치 시 견고한 받침대\n· U헤드 단판 없는 동바리 → 상단에 U헤드 단판 설치, 멍에 전도·이탈 방지\n· 이음은 **같은 품질의 재료**\n· 강재 접속부·교차부는 **볼트·클램프** 등 전용철물로 연결\n· **깔판·받침목 2단 이상 끼우기 금지**(부득이한 경우 제외)\n\n**유형별(제332조의2)**\n· **파이프서포트**: **3개 이상 이어서 사용 금지** / 이을 때 **볼트 4개 이상** / 높이 **3.5m 초과 → 2m 이내마다 수평연결재 2개 방향**\n· **강관틀**: 교차가새 설치 / **최상층 및 5단 이내마다**, 교차가새 방향 **5개 이내마다** 수평연결재 / 띠장틀 설치\n· **조립강주**: 높이 **4m 초과 → 4m 이내마다 수평연결재 2개 방향**\n· **시스템동바리**: 수평재는 수직재와 직각 / 가새재 견고히 / 최상단·최하단 수직재와 받침철물 **겹침 1/3 이상**\n· **보 형식**: 접합부 충분한 걸침 길이 + 용접 고정 / 수평연결재 또는 동바리 추가",
