       "body": "**해체용 기구의 종류**\n· **압쇄기**: 굴착기 장착, 유압조작으로 압축력 파쇄, **소음·진동 적어 도심공사에 주로 사용**\n· **대형 브레이커**: 셔블에 설치, **파쇄력 크고 해체범위 넓으나 소음·진동 심함**\n· **철제 해머**: 크레인에 부착, 충격으로 파쇄\n· **핸드 브레이커**: 압축공기·유압의 급속한 충격력\n· **팽창제**: **광물의 수화반응에 의한 팽창압** 이용\n· **절단기**: 절단톱 고속회전, 기둥·보·바닥·벽체 절단\n\n**취급 유의사항**\n· 압쇄기: 수평 낙하물 방호책 설치 / **파쇄순서 = 슬래브 → 보 → 벽체 → 기둥**\n· 핸드 브레이커: 작업자세 **하향 수직방향** 유지\n· 절단기(톱): 회전날에 접촉방지 커버 부착\n· 팽창제: **천공 직경 30mm~50mm**, **천공간격 30cm~70cm**, 건조한 장소 보관, **개봉된 팽창제 사용 금지**\n\n**해체 작업계획서 내용 7가지**: 해체의 방법 및 **해체 순서도면** / 가설설비·방호설비·환기설비 및 살수·방화설비 등의 방법 / 사업장 내 연락방법 / **해체물의 처분계획** / 해체작업용 기계·기구 작업계획서 / 해체작업용 화약류 사용계획서 / 그 밖에 안전·보건 관련 사항",
