       "body": "**콘크리트 타설작업 시 준수사항(제334조)**\n① 당일 작업 시작 전 **거푸집 및 동바리의 변형·변위 및 지반의 침하 유무** 점검, 이상 시 보수\n② 작업 중 **감시자 배치**로 변형·변위·침하 유무 확인, 이상 시 작업 중지 및 근로자 대피\n③ 거푸집 붕괴 위험 우려 시 **충분한 보강조치**\n④ **설계도서 상의 양생기간 준수**하여 거푸집 및 동바리 해체\n⑤ **편심이 발생하지 않도록 골고루 분산하여 타설**\n\n**타설 시 안전수칙(KCS)**\n· 계획에 의하여 순서대로 실시\n· 타설 도중 거푸집·동바리 이상 유무 확인, 담당자 배치\n· 타설속도는 콘크리트공사 표준시방서에 따름\n· 손수레 운반 시 천천히 운반, 거푸집에 충격 금지, 적당한 간격 유지\n· 운반·타설장비는 작업시작 전 성능 확인, 사용 전·후 점검\n· **한 곳 집중 타설 → 편심하중으로 거푸집 변형·동바리 탈락 → 붕괴사고**\n· **지나친 진동은 거푸집 도괴의 원인**\n\n**배합설계**: **설계기준강도 f_ck = 재령 28일 압축강도** / 배합강도 f_cr = 설계기준강도 × 할증계수\n**다짐**: Slump 8m일 때 다짐시간 **5~15초** 표준 / 효과 = **공극감소, 철근 부착력 증대, 내구성 증대**",
