       "body": "**측압이 커지는 조건 ★★★**\n· **거푸집 부재단면이 클수록**\n· **거푸집 수밀성이 클수록**(투수성이 작을수록)\n· **거푸집의 강성이 클수록**\n· **거푸집 표면이 평활할수록**\n· **시공연도(Workability)가 좋을수록**\n· **철골 또는 철근량이 적을수록**\n· **외기온도가 낮을수록, 습도가 높을수록**\n· **콘크리트의 타설속도가 빠를수록**\n· **콘크리트의 다짐이 과할수록**\n· **콘크리트의 슬럼프가 클수록**\n· **콘크리트의 비중이 클수록**\n※ 타설 높이가 증가하면 측압은 증가하나 **일정 높이 이상이 되면 감소**\n\n**옹벽의 안정조건 ★★★**\n| 구분 | 식 | 기준 |\n|---|---|---|\n| **활동** | 활동에 저항하려는 힘 / 활동하려는 힘 | **≥ 1.5** |\n| **전도** | 저항 모멘트 / 전도 모멘트 | **≥ 2.0** |\n| **지반 지지력(침하)** | 지반의 허용지지력 / 지반에 작용하는 최대하중 | **≥ 1.0** |\n\n**옹벽의 종류**: 중력식(자중으로 토압 대항) / 반중력식(벽두께 얇게 + 철근) / 역T형(기초 슬래브 일부 돌출) / 부벽식(부벽으로 지탱)",
       "id": "S6-CH6-n9"
